import {SchoolTHREE as THREE,schoolBox,schoolMaterial,schoolRod} from './core.js?v=76a';
// Functional book, brush, bottle and parcel props use the same rounded Schoolbus construction kit.
export function giveNeighbourJob(e,job){if(e.job===job&&e.jobProp)return;e.jobProp?.removeFromParent();e.jobStation?.removeFromParent();e.job=job;const g=e.jobProp=new THREE.Group();g.name=job+' activity prop';(e.kb?.bones[6]||e.armR||e.g).add(g);const box=(w,h,d,x,y,z,c)=>{const m=new THREE.Mesh(schoolBox(w,h,d),schoolMaterial(c));m.position.set(x,y,z);g.add(m);return m;};
 if(job==='read'){box(.48,.06,.34,0,-.04,.1,0x81b9c8);box(.42,.035,.29,0,0,.1,0xfff4df);box(.02,.02,.29,0,.025,.1,0xe3bd78);}
 else if(job==='water'){box(.18,.26,.18,0,-.05,.05,0xa9d7bd);schoolRod(new THREE.Vector3(.06,.06,.05),new THREE.Vector3(.25,.16,.12),.035,schoolMaterial(0x88bcb4),g);}
 else if(job==='paint'){schoolRod(new THREE.Vector3(0,-.2,0),new THREE.Vector3(0,.2,0),.025,schoolMaterial(0xf1cb82),g);box(.09,.12,.04,0,.24,0,0xdb9fbe);}
 else if(job==='sweep'){schoolRod(new THREE.Vector3(0,-.48,0),new THREE.Vector3(0,.3,0),.025,schoolMaterial(0xd7b67e),g);box(.34,.18,.09,0,-.50,0,0xeacb88);}
 else if(job==='deliver'){box(.34,.24,.28,0,-.06,.05,0xecc296);box(.04,.26,.3,0,-.06,.05,0xf1aebc);}
 if(['paint','water'].includes(job)){const stand=e.jobStation=new THREE.Group();stand.position.set(.48,0,.65);e.g.add(stand);const add=(geo,col,x,y,z)=>{const m=new THREE.Mesh(geo,schoolMaterial(col));m.position.set(x,y,z);stand.add(m);return m;};if(job==='paint'){add(schoolBox(.65,.65,.07),0xf1cba2,0,.8,0);add(schoolBox(.53,.53,.025),0xfff7df,0,.8,.05);for(let i=0;i<3;i++)add(new THREE.SphereGeometry(.07,8,6),[0x8fc9bd,0xf1bb8a,0xd9abc5][i],(i-1)*.13,.8+Math.sin(i)*.15,.08);for(const x of [-.25,.25])add(schoolBox(.04,.65,.05),0xd9bd92,x,.32,0);}else{add(new THREE.CylinderGeometry(.24,.18,.32,12),0xe6bfaa,0,.16,0);for(let i=0;i<4;i++){const a=i*1.57;add(new THREE.SphereGeometry(.12,10,8),0x8ec67d,Math.sin(a)*.1,.42+Math.cos(i)*.06,Math.cos(a)*.1);add(new THREE.SphereGeometry(.065,10,8),[0xebafbe,0xf1d486][i%2],Math.sin(a)*.13,.59+Math.cos(i)*.06,Math.cos(a)*.13);}}}g.visible=!['walk','dance'].includes(job);return g;}
export function tickNeighbourJob(e,t,{busy=false,reduced=false}={}){if(!e.jobProp)return;e.jobProp.visible=!busy&&!['walk','dance'].includes(e.job);e.jobProp.rotation.set(0,0,0);if(!reduced&&e.job==='water')e.jobProp.rotation.z=Math.sin(t*1.8)*.35;if(!reduced&&e.job==='sweep')e.jobProp.rotation.x=Math.sin(t*2)*.28;}
export function jobPose(job){return job==='read'?'type':job==='dance'?'clap':job==='water'?'give':job==='paint'?'type':job==='deliver'?'give':null;}
